// Evita repetir la MISMA alerta cada minuto (espera 10 min).
// Nota: al probar con "Execute workflow" a mano, n8n no guarda esta memoria,
// así que en pruebas manuales siempre alerta. Con el flujo activo sí la guarda.
function primeraVez(clave, minutos = 10) {
  const sd = $getWorkflowStaticData('global');
  const ahora = Date.now();
  sd.vistos = sd.vistos || {};
  for (const k of Object.keys(sd.vistos)) {
    if (ahora - sd.vistos[k] > 24 * 3600 * 1000) delete sd.vistos[k];
  }
  if (sd.vistos[clave] && ahora - sd.vistos[clave] < minutos * 60 * 1000) return false;
  sd.vistos[clave] = ahora;
  return true;
}

// R3: conexión fuera de horario (entre 11 pm y 6 am).
// PARA PROBAR DE DÍA: cambie temporalmente HORA_INICIO a la hora actual (ej. 15) y documéntelo.
const HORA_INICIO = 23;   // 11 pm
const HORA_FIN = 6;       // 6 am
const filas = $input.all().map(i => i.json).filter(r => r.usename);
if (filas.length === 0) return [];
const h = filas[0].hora_actual;
const fueraDeHorario = HORA_INICIO > HORA_FIN
  ? (h >= HORA_INICIO || h < HORA_FIN)
  : (h >= HORA_INICIO && h < HORA_FIN);
if (!fueraDeHorario) return [];
const clave = 'R3:' + filas.map(r => r.usename + r.inicio).sort().join('|');
if (!primeraVez(clave)) return [];
return [{ json: {
  codigo: 'R3',
  severidad: 'ADVERTENCIA',
  tipo: 'Conexión fuera de horario laboral',
  tabla: 'pg_stat_activity',
  detalle: 'Sesiones: ' + filas.map(r => `${r.usename} desde ${r.client_addr || 'local'} (inicio ${r.inicio})`).join('; '),
  query: 'SELECT usename, client_addr, backend_start FROM pg_stat_activity ...',
  usuario: [...new Set(filas.map(r => r.usename))].join(', '),
  accion: 'Verificar con el dueño de la cuenta si el acceso estaba autorizado.'
}}];
